-- Short questions
(6, 22, 16, 22, '19cae243-b694-4804-afb0-c1bb80f9f33f', 'short', 'মূলদ সংখ্যা ও অমূলদ সংখ্যার মধ্যে পার্থক্য লেখ।', NULL, NULL, NULL, NULL, NULL, 'মূলদ সংখ্যা p/q আকারে প্রকাশ করা যায় (q≠0), অমূলদ সংখ্যা করা যায় না।', '[]'),
(6, 22, 16, 23, '19cae243-b694-4804-afb0-c1bb80f9f33f', 'short', 'সংখ্যারেখায় √5 এর অবস্থান নির্ণয় করার পদ্ধতি বর্ণনা কর।', NULL, NULL, NULL, NULL, NULL, 'পিথাগোরাসের উপপাদ্য ব্যবহার করে √5 = √(1²+2²) নির্ণয় করা যায়।', '[{"board":"কুমিল্লা বোর্ড","year":"2023"}]'),
(6, 22, 17, 24, '19cae243-b694-4804-afb0-c1bb80f9f33f', 'short', 'সূচকের ভাগ নিয়মটি উদাহরণসহ ব্যাখ্যা কর।', NULL, NULL, NULL, NULL, NULL, 'a^m ÷ a^n = a^(m-n)। যেমন: 5^4 ÷ 5^2 = 5^(4-2) = 5² = 25।', '[]'),
(6, 22, 17, 25, '19cae243-b694-4804-afb0-c1bb80f9f33f', 'short', 'প্রমাণ কর যে, log(ab) = log a + log b।', NULL, NULL, NULL, NULL, NULL, 'ধরি a = 10^x, b = 10^y। তাহলে ab = 10^(x+y)। অতএব log(ab) = x+y = log a + log b।', '[{"board":"ময়মনসিংহ বোর্ড","year":"2024"}]'),
(6, 22, 16, 22, '19cae243-b694-4804-afb0-c1bb80f9f33f', 'short', '√3 যে অমূলদ সংখ্যা তা প্রমাণ কর।', NULL, NULL, NULL, NULL, NULL, 'বিরোধ পদ্ধতিতে প্রমাণ: ধরি √3 মূলদ, তাহলে √3 = p/q। বর্গ করলে 3 = p²/q², অর্থাৎ p² = 3q²। এটি দেখায় p, 3 দ্বারা বিভাজ্য, যা বিরোধ সৃষ্টি করে।', '[]'),

